def choose_move(observation):
    def is_num(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def coord_like(v):
        return (
            isinstance(v, (list, tuple))
            and len(v) >= 2
            and is_num(v[0])
            and is_num(v[1])
        )

    def get_coord(v):
        if coord_like(v):
            return [int(v[0]), int(v[1])]
        if isinstance(v, dict):
            for kx, ky in (("x", "y"), ("col", "row"), ("cx", "cy")):
                if is_num(v.get(kx)) and is_num(v.get(ky)):
                    return [int(v.get(kx)), int(v.get(ky))]
        return None

    def first_coord(obj):
        if coord_like(obj):
            return [int(obj[0]), int(obj[1])]
        if isinstance(obj, dict):
            for key in ("position", "pos", "location", "loc", "coord", "coordinates", "agent_pos", "self_pos"):
                c = get_coord(obj.get(key))
                if c is not None:
                    return c
            for key in ("agent", "self", "me", "player"):
                sub = obj.get(key)
                c = first_coord(sub)
                if c is not None:
                    return c
        return None

    def deep_find_coords(obj, limit=32):
        out = []
        seen = 0
        def rec(v):
            nonlocal seen
            if seen >= limit:
                return
            seen += 1
            c = get_coord(v)
            if c is not None:
                out.append(c)
                return
            if isinstance(v, dict):
                for kk in v:
                    rec(v.get(kk))
                    if seen >= limit:
                        return
            elif isinstance(v, (list, tuple)):
                for item in v:
                    rec(item)
                    if seen >= limit:
                        return
        rec(obj)
        return out

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_step(v):
        if v < -1:
            return -1
        if v > 1:
            return 1
        return v

    def sign(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def in_bounds(p, w, h):
        return p[0] >= 0 and p[1] >= 0 and p[0] < w and p[1] < h

    obs = observation if isinstance(observation, dict) else {}
    me = first_coord(obs)
    if me is None:
        me = [0, 0]

    # Grid / map extraction
    grid = None
    for key in ("grid", "map", "board", "world", "terrain", "tiles"):
        g = obs.get(key)
        if isinstance(g, list) and g:
            grid = g
            break

    h = len(grid) if isinstance(grid, list) else 0
    w = len(grid[0]) if h and isinstance(grid[0], list) else 0

    walls = set()
    hazards = set()
    resources = []
    enemies = []
    allies = []
    neutral_cells = []
    frontier_cells = []

    if isinstance(grid, list) and h and w:
        for y in range(h):
            row = grid[y]
            if not isinstance(row, list):
                continue
            for x in range(min(w, len(row))):
                cell = row[x]
                if cell in (1, "#", "W", "wall", "blocked", True):
                    walls.add((x, y))
                elif cell in (-1, "X", "hazard", "lava", "trap"):
                    hazards.add((x, y))
                elif cell in (0, ".", None, "empty", "neutral"):
                    neutral_cells.append([x, y])
                elif cell in (2, "R", "resource", "food", "gem", "coin"):
                    resources.append([x, y])
                elif cell in (3, "E", "enemy", "opponent", "threat"):
                    enemies.append([x, y])
                elif cell in (4, "A", "ally", "friend"):
                    allies.append([x, y])
                elif isinstance(cell, dict):
                    if cell.get("resource") or cell.get("value") in ("resource", "food"):
                        resources.append([x, y])
                    if cell.get("enemy") or cell.get("owner") == "enemy":
                        enemies.append([x, y])
                    if cell.get("owner") in (None, "neutral", 0):
                        neutral_cells.append([x, y])

    # General observation keys for objects
    for key in ("resources", "resource_positions", "foods", "food", "targets", "goals", "pickups"):
        items = obs.get(key)
        if isinstance(items, (list, tuple)):
            for it in items:
                c = get_coord(it)
                if c is not None:
                    resources.append(c)

    for key in ("enemies", "enemy_positions", "opponents", "opponent_positions", "threats", "pursuers"):
        items = obs.get(key)
        if isinstance(items, (list, tuple)):
            for it in items:
                c = get_coord(it)
                if c is not None:
                    enemies.append(c)

    for key in ("allies", "ally_positions", "friends"):
        items = obs.get(key)
        if isinstance(items, (list, tuple)):
            for it in items:
                c = get_coord(it)
                if c is not None:
                    allies.append(c)

    for key in ("frontier", "frontiers", "border", "borders", "territory_targets"):
        items = obs.get(key)
        if isinstance(items, (list, tuple)):
            for it in items:
                c = get_coord(it)
                if c is not None:
                    frontier_cells.append(c)

    # Infer game mode
    mode = obs.get("mode")
    if not isinstance(mode, str):
        if resources:
            mode = "resource_collection"
        elif enemies:
            mode = "pursuit_evasion"
        else:
            mode = "territory_control"

    candidates = [(0, 0)] + [(dx, dy) for dx in (-1, 0, 1) for dy in (-1, 0, 1) if not (dx == 0 and dy == 0)]

    def blocked(p):
        if (p[0], p[1]) in walls or (p[0], p[1]) in hazards:
            return True
        if w and h and not in_bounds(p, w, h):
            return True
        return False

    def score_move(dx, dy):
        nx, ny = me[0] + dx, me[1] + dy
        np = [nx, ny]
        if blocked(np):
            return -10**9

        s = 0

        # Prefer not to stand still unless no better option
        if dx == 0 and dy == 0:
            s -= 2

        # Avoid immediate danger
        if enemies:
            dmin = min(manhattan(np, e) for e in enemies)
            s += dmin * 3
            if dmin <= 1:
                s -= 20
            if dmin == 2:
                s -= 5

        if mode == "resource_collection":
            if resources:
                d = min(manhattan(np, r) for r in resources)
                s += 30 - 4 * d
            if frontier_cells:
                d = min(manhattan(np, f) for f in frontier_cells)
                s += max(0, 8 - d)
        elif mode == "pursuit_evasion":
            if enemies:
                d = min(manhattan(np, e) for e in enemies)
                s += 18 + 5 * d
            if resources:
                d = min(manhattan(np, r) for r in resources)
                s += max(0, 3 - d)
        else:  # territory_control
            if frontier_cells:
                d = min(manhattan(np, f) for f in frontier_cells)
                s += 20 - 3 * d
            elif neutral_cells:
                d = min(manhattan(np, c) for c in neutral_cells)
                s += 12 - 2 * d
            if resources:
                d = min(manhattan(np, r) for r in resources)
                s += max(0, 4 - d)

        # Soft preference for movement toward map center if nothing else
        if w and h:
            center = [w // 2, h // 2]
            s += max(0, 4 - manhattan(np, center))

        return s

    best = None
    best_score = -10**18
    for dx, dy in candidates:
        sc = score_move(dx, dy)
        if sc > best_score:
            best_score = sc
            best = [dx, dy]

    if best is None:
        best = [0, 0]
    return best

